from hermes_tools import terminal
r=terminal("python3 - <<'PY'
# Clearly tile from demo output has periods of 5 rows and 5 columns. Test marks form an underdetermined subset, but tile must be aligned to grid origin?
# In demo3 row18 col0 output=6, row18%5=3, tile row3 col0=6; row23 col0 output=6, row23%5=3 also 6. Test marker row17 col7=6, tile r2 c2=5 conflicts. Could be output phase pinned by top-left marker alignment, use translation to match test.
# Original test has 5 marks along diagonal from (5,0) with color5; 6 starts (10,0), color6. Find shifts dr,dc modulo 5 for the 5x5 tile such that ALL visible marker cells match.
rows=['52675','55267','75526','67552','26755']
marks=[]
for r in range(5,18): marks.append((r,r-5,5))
for r in range(10,18): marks.append((r,r-10,6))
for dr in range(5):
 for dc in range(5):
  if all(int(rows[(r+dr)%5][(c+dc)%5])==v for r,c,v in marks):
   print('shift',dr,dc)
PY")
print(r['output'])

